  out.length = 0
  for (const k of [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    out.push(`${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
  }
  out.push(`total allowed=${totA} denied=${totD}`)
}
